def norm(shape):
 mr=min(x for x,y in shape); mc=min(y for x,y in shape); return frozenset((x-mr,y-mc) for x,y in shape)
def transforms(shape):
 out=set()
 for flip in [1,-1]:
  for rot in range(4):
   pts=[]
   for x,y in shape:
    x,y=x*flip,y
    for _ in range(rot): x,y=y,-x
    pts.append((x,y))
   out.add(norm(pts))
 return out
